{
  "name": "bench-debug-limiter",
  "version": "1.0.0",
  "private": true,
  "type": "commonjs",
  "scripts": {
    "test": "node --test"
  }
}
'use strict';

// createLimiter accepts a positive integer Number concurrency, otherwise throws
// RangeError. It returns run(fn), which always returns a Promise. run rejects
// non-functions with TypeError. Queued functions start in submission order, with
// at most concurrency functions running. Values, promises, synchronous throws,
// and promise rejections settle only the corresponding run result; the limiter
// must remain usable afterward. Each function is invoked once, with no arguments.
function createLimiter(concurrency) {
  if (!Number.isInteger(concurrency) || concurrency < 1) {
    throw new RangeError('Concurrency must be a positive integer');
  }
  let active = 0;
  const queue = [];

  function drain() {
    while (active < concurrency && queue.length > 0) {
      const job = queue.shift();
      active += 1;
      Promise.resolve().then(job.fn).then(
        value => {
          job.resolve(value);
          active -= 1;
          drain();
        },
        error => {
          job.reject(error);
        }
      );
    }
  }

  return function run(fn) {
    if (typeof fn !== 'function') return Promise.reject(new TypeError('Task must be a function'));
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      drain();
    });
  };
}

module.exports = { createLimiter };
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createLimiter } = require('../src/limit');
const tick = () => new Promise(resolve => setImmediate(resolve));
function deferred() {
  let resolve;
  const promise = new Promise(done => { resolve = done; });
  return { promise, resolve };
}

test('enforces the concurrency limit and starts queued work in order', { timeout: 2000 }, async () => {
  const run = createLimiter(2);
  const gates = Array.from({ length: 4 }, deferred);
  const started = [];
  const results = gates.map((gate, index) => run(async () => {
    started.push(index);
    await gate.promise;
    return index * 10;
  }));
  await tick();
  assert.deepEqual(started, [0, 1]);
  gates[1].resolve();
  await tick();
  assert.deepEqual(started, [0, 1, 2]);
  gates[0].resolve();
  await tick();
  assert.deepEqual(started, [0, 1, 2, 3]);
  gates[2].resolve();
  gates[3].resolve();
  assert.deepEqual(await Promise.all(results), [0, 10, 20, 30]);
});

test('queued work still completes when a task rejects', { timeout: 2000 }, async () => {
  const run = createLimiter(1);
  const error = new Error('task failed');
  const rejected = run(async () => { throw error; });
  const rejection = assert.rejects(rejected, actual => actual === error);
  const next = run(() => 42);
  await rejection;
  assert.equal(await next, 42);
  assert.equal(await run(() => 'still usable'), 'still usable');
});


